\begin{tikzpicture}[>=stealth,line cap=round,line join=round,font=\sffamily\small]
% ground
\draw[thick] (-0.5,0)--(6.5,0);
% vertical stick
\draw[thick] (2.5,0)--(2.5,2.2);
\node[font=\footnotesize] at (2.5,2.5) {vertical stick};
% morning long shadow
\draw[thick] (2.5,0)--(0.2,0);
\fill (0.2,0) circle (1.5pt);
\node[font=\footnotesize] at (0.2,-0.35) {long};
% noon short shadow
\draw[thick] (2.5,0)--(2.9,0);
\fill (2.9,0) circle (1.5pt);
\node[font=\footnotesize] at (3.5,-0.35) {shortest};
% afternoon long shadow
\draw[thick] (2.5,0)--(5.5,0);
\fill (5.5,0) circle (1.5pt);
\node[font=\footnotesize] at (5.5,-0.35) {long};
% sun high
\fill[yellow!70!orange] (2.9,3.3) circle (0.28);
\node[font=\footnotesize] at (2.9,3.75) {Sun high};
\draw[->,thin] (2.9,3.0)--(2.7,2.3);
\end{tikzpicture}
